    asn1: Avoid undefined shifts by adding explicit cast

    The error was:
    asn1.c:681:23: runtime error: left shift of 255 by 24 places cannot be represented in type 'int'
                #0 0x5e9b11 in decode_bit_field opensc/src/libopensc/asn1.c:681:23

    https://bugs.chromium.org/p/oss-fuzz/issues/detail?id=18487

diff --git a/src/libopensc/asn1.c b/src/libopensc/asn1.c
index 66d4184d..c68f62c9 100644
--- a/src/libopensc/asn1.c
+++ b/src/libopensc/asn1.c
@@ -641,81 +641,81 @@ static int encode_bit_string(const u8 * inbuf, size_t bits_left, u8 **outbuf,

                *out = 0;
                if (bits_left < 8) {
                        bits_to_go = bits_left;
                        skipped = 8 - bits_left;
                }
                if (invert) {
                        for (i = 0; i < bits_to_go; i++)
                                *out |= ((*in >> i) & 1) << (7 - i);
                } else {
                        *out = *in;
                        if (bits_left < 8)
                                return SC_ERROR_NOT_SUPPORTED; /* FIXME */
                }
                bits_left -= bits_to_go;
                out++, in++;
        }
        out = *outbuf;
        out[0] = skipped;
        return 0;
 }

 /*
  * Bitfields are just bit strings, stored in an unsigned int
  * (taking endianness into account)
  */
 static int decode_bit_field(const u8 * inbuf, size_t inlen, void *outbuf, size_t outlen)
 {
        u8              data[sizeof(unsigned int)];
        unsigned int    field = 0;
        int             i, n;

        if (outlen != sizeof(data))
                return SC_ERROR_BUFFER_TOO_SMALL;

        n = decode_bit_string(inbuf, inlen, data, sizeof(data), 1);
        if (n < 0)
                return n;

        for (i = 0; i < n; i += 8) {
-               field |= (data[i/8] << i);
+               field |= ((unsigned int) data[i/8] << i);
        }
        memcpy(outbuf, &field, outlen);
        return 0;
 }

 static int encode_bit_field(const u8 *inbuf, size_t inlen,
                            u8 **outbuf, size_t *outlen)
 {
        u8              data[sizeof(unsigned int)];
        unsigned int    field = 0;
        size_t          i, bits;

        if (inlen != sizeof(data))
                return SC_ERROR_BUFFER_TOO_SMALL;

        /* count the bits */
        memcpy(&field, inbuf, inlen);
        for (bits = 0; field; bits++)
                field >>= 1;

        memcpy(&field, inbuf, inlen);
        for (i = 0; i < bits; i += 8)
                data[i/8] = field >> i;

        return encode_bit_string(data, bits, outbuf, outlen, 1);
 }

